quickStart.sql:
ATTACH 'hello' AS qf_airport_demo (
  TYPE airport, LOCATION 'grpc+tls://hello-airport.query.farm'
);
SELECT greeting || ', ' || first_name AS greeting
FROM qf_airport_demo.static.greetings AS g
JOIN qf_airport_demo.static.people AS p ON p.language = g.language
ORDER BY greeting
LIMIT 3;
DETACH qf_airport_demo;
